<?php

declare(strict_types=1);namespace backend\controllers;use backend\components\AdminController;use common\models\PaymentOrder;use common\services\{WalletService,AuditService};use Yii;use yii\data\ActiveDataProvider;use yii\web\NotFoundHttpException;
final class PaymentController extends AdminController { protected string $permission='managePayments'; public function actionIndex():string{return $this->render('index',['dataProvider'=>new ActiveDataProvider(['query'=>PaymentOrder::find()->orderBy(['id'=>SORT_DESC]),'pagination'=>['pageSize'=>30]])]);}public function actionApprove(int $id){if(!Yii::$app->request->isPost)throw new \yii\web\MethodNotAllowedHttpException();$o=PaymentOrder::findOne($id);if(!$o)throw new NotFoundHttpException();if($o->status===PaymentOrder::STATUS_NEW){$tx=Yii::$app->db->beginTransaction();try{(new WalletService())->credit((int)$o->user_id,(float)$o->amount,'topup','Пополнение баланса','payment',(int)$o->id);$o->status=PaymentOrder::STATUS_PAID;$o->paid_at=date('Y-m-d H:i:s');$o->updated_at=date('Y-m-d H:i:s');$o->save(false);$tx->commit();AuditService::log('admin.payment.approve','payment',(string)$id,['amount'=>$o->amount]);}catch(\Throwable $e){$tx->rollBack();throw $e;}}return $this->redirect(['index']);}public function actionCancel(int $id){if(Yii::$app->request->isPost){$o=PaymentOrder::findOne($id);if($o&&$o->status===PaymentOrder::STATUS_NEW){$o->status=PaymentOrder::STATUS_CANCELLED;$o->updated_at=date('Y-m-d H:i:s');$o->save(false);}}return $this->redirect(['index']);}}
